// A regra mora na API (cliente vinculado, janela de 24 h, template). O n8n só dá o horário.
const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const headers = { 'Content-Type': 'application/json', 'X-Internal-Token': $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '' };
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: `${apiUrl}/internal/reminders/reservations`,
  headers,
  body: {},
  json: true,
  timeout: 120000,
});
// Quantos foram enviados, pulados ou falharam fica na saída da execução.
return [{ json: result }];
